      "皇城之上挂着第二轮血日。它不像血月那样张扬，它挂在日头旁边，像一枚被盖进官印里的火漆。街上很少有人抬头。不抬头的人不是没有眼睛，是学会了把命写成税之后，就不必再问天。茶楼里说书先生把“国师养仙胎”讲成祥瑞。讲到后来声音发干，自己也停了。有人在他碗底压了一张纸：天牢有证人，暗巷有逆谱，朝堂有不敢说的口。",
      "裴衡曾经是青冥内门首席，最能护人的那把剑。覆灭那夜上方把护生剑谱改成收命之阵，他没有先斩掌教，他开了山门。开门时他说：我成全人间。成全的意思是：让人间继续交税，好让上方不把九州当成欠账一次性收走。他怕的不是死。他怕“人可以不交税”四个字一旦教给全世界，上方会把整个人间写成一张总账。",
      "炉在国师府最深处。纹路你在废祠井底见过，在血月祭坛见过。见过的意思是：这一炉不是新发明，是把一座城、再把九州，都写成同一本税册。你若此刻只带一把剑去掀桌，他会把你讲成乱臣。乱臣两个字一旦落地，证人会先死，逆谱会先烧，朝堂会先把你写成下一个税。所以这一章不是立刻掀桌。是先把三证找齐。",
      "天牢要的是一个还活着的舌头。证人见过炉怎么点，也见过名册怎么从废祠走到帝京。救出他，朝堂可用人证；只取供词更安全，人却可能被灭口。暗巷里有一份逆谱，谱上把仙胎炉的纹路写成罪，不写成祥瑞。带走逆谱，朝堂更硬；烧掉逆谱，功德会涨，裴衡会笑你又把证据送进火里。朝堂上有一句不敢说的话：有人看见国师袖里那半块青冥令。",
      "苏晚晴若已跟你入京，会在暗巷里替你挡第一刀。阿霜若还在，会把你往人少的地方拽。顾清玄的剑意会在屋脊上闪一下，像提醒你：帝京不是断崖，第一剑不够快也没关系，先问人还算不算人。她们不必你回情缘菜单一扇一扇去点。她们会自己走来。走来的时候，帝京的血日会淡一点点。",
      "三证各是一枚钉子。钉子钉进炉前，裴衡的笑才会第一次收一收。收一收，不是怕死。是怕那四个字再次被说圆。说圆了，炉就会显得像罪，而不是祥瑞。你袖中叠着废祠的名册、南疆的雨、血月的誓和东海的焰。帝京要的不是你立刻拔剑。是你先证明：炉里烧的不是祥瑞，是人。",
