      "皇城之上挂着第二轮血日。它不像血月那样张扬，它挂在日头旁边，像一枚被盖进官印里的火漆。街上很少有人抬头。不抬头的人不是没有眼睛，是学会了把命写成税之后，就不必再问天。茶楼里有人说国师裴衡昨夜又救了一城的灾，说得极真。真的灾后面往往有真的炉。",
      "裴衡曾经是青冥内门首席，最能护人的那把剑。覆灭那夜上方把护生剑谱改成收命之阵，他没有先斩掌教，他开了山门。开门时他说：我成全你们活。活的方法是交税。交税交到今夜，交成了一炉用万民气运点燃的长生。他比邪修难斩，因为他会把叛变说成成全。成全两个字，比刀更快。",
      "天牢要的是一个还活着的舌头。证人见过炉怎么点，也见过名册怎么从废祠走到帝京。救出他，朝堂可用人证；只取供词更安全，人却可能在后文里变成又一张纸。暗巷要的是逆谱。谱上有太一火漆，有护生被改成收命的那一笔。烧了谱，功德在，物证不在。裴衡会笑。笑得很温和。",
      "朝堂要的不是一声怒喝，是一句能把废祠、血月、天牢串起来的话：国师不是在养仙胎，是在提前把九州写成税册。当殿揭开，声望会涨，棋局会提前摊开；暗通给尚能信的人，后文少一场朝堂风波。长公主萧景行没有退席。她看着你，像看着一柄可以共主山河的剑，也像看着一个可能把江山一起掀翻的人。",
      "苏晚晴若已跟你入京，会在暗巷里替你挡第一刀。阿霜若还在，会把你往人少的地方拽。顾清玄的剑意会在屋脊上闪一下，像提醒你：帝京不是断崖，第一剑不够快也没关系，先问人还算不算人。苏沐的汤会在茶楼后巷温着。花千影会把一张笑面留给对面喝酒的人。她们不必你回菜单。她们已经把这一夜写成会跟你走进炉前的夜。",
      "三证不齐不要掀桌。掀桌的人若手里没有舌头、没有逆谱、没有一句能说圆的话，裴衡会把你的侠义，讲成一场恰好可以被税册吞掉的乱。乱的死，上方最喜欢。喜欢的死很干净。干净的死进不了残碑上那一句：人该怎么活。活着把三证叠在炉前，才配决定斩他、留他，或把炉据为己用。",
