      "她看见你，把酒葫芦砸过来。葫芦砸在你胸口，酒香混着刀油：“方才坛下那一剑是你吧？路见不平，喝一口。喝完——若还冷，就到我车里来。镖局的规矩，今夜不分男女，只分活人。活人要坐在一起，死气才会退。”",
      "车厢狭小，窄到两个人的膝不得不碰上。她解了劲装外罩，中衣被汗贴在身上，刀横在膝上，却把你的手按在自己腰间止血的布上。布是热的。热的是血，也是她。“别躲。触一下又不会少块肉。少了，我再砍回来。你若嫌烫，就当我把命借你暖一会儿。”她说到后来声音低了，低得不像江湖人，像一个送了太多次别人回家、自己却很少被送到的人。",
      qmTone("红芍","emb")+" 车帘落下时，外面还有哭声。里面只有酒、刀，和她把额头抵上你肩的那一下。抵得很重。重的人，其实最怕你把她只当成一路同行的侠客。"
