      q.oath==="冷眼记阵"
        ? "她没有骂你。骂太轻。她只把剑收回鞘里，走近两步，又停住。停住的距离刚好够你听见她呼吸乱了一拍：“旁观我可以忍一次。南疆那夜你若也只是看，我不会把外套扔给你。你若还想让我贴着你的背走路，今夜就把脸转过来。转过来的意思是——承认你看见了，也承认你还要我。”"
        : "她把你拉进还没塌完的帷幕后面。帷幕上还留着祭纹的残影，残影挡不住她的手。手在抖，吻却很稳。稳得像她在瘴林里等雨的那些夜里，已经把这一吻练习过许多遍：“你把人都背出来了。那我呢。我能不能……也从你背上，爬进你怀里。名册上的霜字淡了一笔。淡的那一笔，我想用来写你。”",
      "远处还有哭声。近处只有她的呼吸，和雨滴落在废铁链上的声音。铁链是松的。人却可以自己走近。这一夜若是错过，后面的天门她仍会来，只是不再把后背完全交给你。后背这种东西，交出去一次，就要用很多个雨夜才能再交一次。",
      qmTone("阿霜","hold")+" 她把名册的灰从你脸上擦掉。擦得很慢。慢的人，其实已经把今夜当成了可以留下的一夜。"
