      "她会把令牌按进你掌心，指尖冰凉，凉完又不肯拿开。国师袖里那半块青冥令，她已经说给你听。帝京的炉就是血月的放大，她也会跟你入京。入京不是私奔。是去把炉前那个人从成全里问出来。问出来之前，今晚这艘船只容得下两个人的呼吸。呼吸可以只是盟印，也可以是吻，也可以是把银面重新戴上、只做引路的人。三种近。三种后文。海都听得见。",
