      "锁骨下那道旧疤在月光里像被人用税册裁过的纸边。她说：命格被剜的那一夜，银面是她给自己留下来的最后一层。一层不够挡潮。潮会把人的声音灌进耳朵里，灌成“你该交税”。她用银面把这句话挡在外面。挡了很多年。挡到你把空年乘上船。",
      "三道灵焰并排立着，像三封没有署名的信。青焰护心，赤焰焚业，玄焰改命。取哪一道，帝京与天门都会不同。她不替你选。不选的人把银面摘到一半就停住：你先说，你是来补命格，来借焰，还是来把我从潮里拉出来一会儿。一会儿也很长。长到够你看清她眼睛。",
      "你在血月若以寿换过命，碑会认得你烧过的三年。认得的碑会把空槽烫一下。烫一下她就知道你做过什么。她不夸。不夸的人把盟印按得更紧：少过寿的人，更不该一个人取赤焰。赤焰会把你剩下的年也当成柴。",
      "真正的机缘不是焰。是她肯把银面摘给一个还在问人该怎么活的人看。看完，你才能决定要盟印、要体温，或只做同行。同行也不少。少的是她把疤也给你看。疤比盟印诚实。诚实的东海这一夜，会把后文的帝京暗巷写成她替你挡刀的那一页。",
