      "你若要盟印，她会把印留在你掌心，自己把银面捡回来戴上。戴上不是拒绝。是把同行写成可以走很远的那种。走很远的人在帝京会替你挡第一刀。挡刀的人不一定让你吻。不吻也可以。也可以的盟，比体温更耐放。",
