      "你若只要同行，她点头。点头时把外袍的扣子重新扣好。扣好的人会把三焰的来路讲完：青焰护神识，护得越紧越疼；赤焰专烧税册，也容易把身边的人烧进业里；玄焰能改门，改之前必须让全城看见炉里烧的是人。讲完她就走在你侧前方。侧前方是护，也是距离。",
      "潮还在涨。涨的潮把三件事拍在碑上：盟印能换后文的挡刀；体温能把空年补短一点；同行能让你取焰时有人提醒你别把人写成柴。无论哪一种，她已经不是银面。不是银面的意思是：后文的帝京、天门，她会自己走来。走来时可能仍戴面。戴面也不妨。你已经看见过底下那张脸。",
