      "“外门苏晚晴。青冥覆灭那夜，我还不够资格死在山门里。”她的声音被潮声一遍遍洗，洗到后来只剩真话，“所以我活到了现在，看着碑，看着海，看着一个又一个被写成天选的人把焰取走。国师袖里有半块令。帝京的炉，就是血月的放大。你若去，我跟你。你若今夜只要焰、不要人——也行。把面还我。面还给我，我还能继续装成守碑的死物。”",
      "海风把她的中衣吹开一线。锁骨下有一道旧疤，像被税册裁过。她没有躲。不躲的意思是：银面后面不是仙，是一个没死透的外门。没死透的人最怕你把她只当成盟友。盟友可以并肩。人却想被你从光里、从海里、从那张银面后面，拉下来。拉下来以后，可以吻，可以拥，可以把面抛进海里，只留她。",
      qmTone("苏晚晴","hold")+" 她的额头抵上你的肩，只抵了一息。一息已经够咸。咸的是海，也是她没在覆灭那夜流完的泪。“取焰之后，面可以还给我，人也可以留下。两件事不是一件事。你选。选完，我便不再把银面戴回去——除非你先把我当成死物。”"
