      "你若走向棋亭，会有人把热汤推过来，把假面推开，把残诗重新抄一遍。抄到“人该怎么活”时，墨会停一下。停一下的人说：王位可以不要。不要的人也能把九州的雨留下来。留下来的雨里，有空村的井绳，有洗剑台的伞，有侧殿的锁。锁和伞都比王冠老实。",
      "你若两处都走，灯会把许多身影叠在墙上。叠得很近。近的终章就是红颜今宵的前一页。前一页要把话说完：谁为你偏过伞，谁给你热过汤，谁把外套盖过来，谁把银面摘给你看，谁把私旨说成枕边话。说完的名字，才配被留下来。留下来不是后宫标签。是这一卷的人还在。",
      "井边若还有两个孩子，赤脚的那个会问：以后还能修仙吗？抱剑的那个会问：人该怎么活？这两个问题比王座更难。难的问题她会和你一起听。听完她不替你答。不答的人把你的手指握住：你答过残碑、答过南疆、答过血月和炉。再答一次。答给孩子听。也答给枕边听。",
      "门还开着。开着的三件事已经放在门槛上：王座能把气运扛起来，也容易把人再写成税；棋亭能把雨留下，却可能把权让给下一个人；两处都走，人会很满，满的长生才像故人肩头的雨。无论哪一种，红颜都会归卷。归卷之后，仍可重温、回廊、游历。游历时她们还会自己走来。",
